  /* Plain-text avatar for the few places that are one line of text. */
  function avatarText(spec) {
    return spec && spec.indexOf(ICON_PREFIX) !== 0 ? spec + ' ' : '';
  }

  var BADGE_SHAPES = ['heater', 'spade', 'round', 'pointed', 'banner', 'hex', 'kite', 'blade'];
  var BADGE_COLORS = [
    { key: 'crimson', a: '#ff2e2e', b: '#7a0d0d' }, { key: 'gold',   a: '#ffc93c', b: '#8a5a00' },
    { key: 'steel',   a: '#c9d3e2', b: '#4a5364' }, { key: 'jade',   a: '#26d07c', b: '#0b5c37' },
    { key: 'azure',   a: '#3ba6ff', b: '#0d3f7a' }, { key: 'violet', a: '#a86bff', b: '#3d1a7a' },
    { key: 'ember',   a: '#ff6a1f', b: '#7a2c05' }, { key: 'bone',   a: '#e8e2d4', b: '#5a5346' }
  ];
  var SHAPE_PATH = {
    heater:  'M8 6h84v40c0 26-19 42-42 52C27 88 8 72 8 46Z',
    spade:   'M8 6h84v52L50 98 8 58Z',
    round:   'M50 4a46 46 0 1 1 0 92a46 46 0 1 1 0-92Z',
    pointed: 'M50 3l42 15v34c0 24-18 38-42 46C26 90 8 76 8 52V18Z',
    banner:  'M12 4h76v78L50 96 12 82Z',
    hex:     'M50 3l40 23v48L50 97 10 74V26Z',
    kite:    'M50 2l44 34-44 62L6 36Z',
    blade:   'M14 6h72l-8 46c-3 20-14 32-28 46-14-14-25-26-28-46Z'
  };

  function badgeOf(league) {
    var b = (league && league.badge) || {};
    var seed = 0, id = (league && (league.id || league.name)) || '';
    for (var i = 0; i < id.length; i++) seed = (seed * 31 + id.charCodeAt(i)) >>> 0;
    /* Unsigned shifts: the hash is a full 32-bit value, and a signed >> turns
       anything past 2^31 negative, which indexes off the front of the array. */
    return {
      shape:  b.shape  || BADGE_SHAPES[seed % BADGE_SHAPES.length],
      color:  b.color  || BADGE_COLORS[(seed >>> 3) % BADGE_COLORS.length].key,
      emblem: b.emblem || GI_CRESTS[(seed >>> 6) % GI_CRESTS.length]
    };
  }

  /* Shield + emblem, composed at render time. Eight shapes x eight colours x
     56 emblems is ~3,500 distinct badges from a handful of paths. */
  function leagueBadgeHtml(league, size) {
    return badgeHtml(badgeOf(league), size);
  }

  /* The same drawing from a plain {shape,color,emblem}, so the shop can show
     a choice before it is made. */
  function badgeHtml(b, size) {
    var c = BADGE_COLORS.filter(function (x) { return x.key === b.color; })[0] || BADGE_COLORS[0];
    var gid = 'bg' + b.color;
    return '<span class="lbadge lbadge-' + (size || 'md') + '">' +
      '<svg viewBox="0 0 100 100" aria-hidden="true" focusable="false">' +
        '<defs><linearGradient id="' + gid + '" x1="0" y1="0" x2="0" y2="1">' +
          '<stop offset="0" stop-color="' + c.a + '"/>' +
          '<stop offset="1" stop-color="' + c.b + '"/></linearGradient></defs>' +
        '<path d="' + SHAPE_PATH[b.shape] + '" fill="url(#' + gid + ')" ' +
          'stroke="rgba(0,0,0,.45)" stroke-width="3"/>' +
        '<path d="' + SHAPE_PATH[b.shape] + '" fill="none" ' +
          'stroke="rgba(255,255,255,.35)" stroke-width="1.5"/>' +
      '</svg>' +
      '<span class="lbadge-em">' + iconSvg(b.emblem) + '</span>' +
    '</span>';
  }

  /* A fighter's banner is their lifetime rank — derived from points they
     already have, so there is nothing to store and nothing to award. */
  /* The raid, bounty and combo used to push the table below the fold. They
     fold into one strip now, and the strip says enough when shut that you only
     open it if something needs doing. */
  function paintWeekChips() {
    var c = [];
    if (state.chip.raid)   c.push(state.chip.raid);
    if (state.chip.bounty) c.push(state.chip.bounty);
    if (state.chip.combo)  c.push(state.chip.combo);
    var box = $('#weekChips'); if (!box) return;
    var wb = $('#weekBox');
    wb.hidden = !c.length;
    /* Open itself when today actually needs something — a live bounty you have
       not done. Otherwise it stays folded and the table starts at the top. */
    if (!state.weekBoxTouched && state.chip.bounty && state.chip.bounty.urgent) wb.open = true;
    box.innerHTML = c.map(function (x) {
      return '<span class="chip' + (x.on ? ' on' : '') + '">' + x.t + '</span>';
    }).join('');
  }

  /* A raid is the one job the whole league carries together for a week. The
     target scales with headcount, so a group of 8 and a group of 28 both get
     something that needs everybody rather than one strong person. */
  async function loadRaid() {
    var box = $('#raidCard'); if (!box) return;
    var r = await sb.rpc('current_raid', { p_league: state.leagueId });
    var d = r.error ? null : (r.data && r.data[0]);
    if (!d) { box.hidden = true; state.chip.raid = null; paintWeekChips(); return; }
    var pct = Math.min(100, Number(d.progress) / Number(d.target) * 100);
    var left = Math.max(0, Number(d.target) - Number(d.progress));
    box.hidden = false;
    box.className = 'raid' + (d.done ? ' done' : '');
    box.innerHTML =
      '<div class="raid-h"><span class="raid-t">LEAGUE RAID</span>' +
        '<span class="raid-n">' + esc(d.name) + '</span>' +
        (d.done ? '<span class="raid-b">CLEARED</span>' : '') + '</div>' +
      '<p class="raid-d">' + esc(d.descr) + ' — together, before Sunday.</p>' +
      '<div class="raid-bar"><span style="width:' + pct.toFixed(1) + '%"></span></div>' +
      '<div class="raid-f">' +
        '<span><b>' + num(d.progress) + '</b> / ' + num(d.target) + ' ' + esc(d.unit) + '</span>' +
        '<span>' + (d.done
          ? 'The whole league scores'
          : num(left) + ' to go · ' + d.members + ' of you') + '</span>' +
      '</div>' +
      (d.top_name ? '<p class="raid-top">Carrying it: <b>' + esc(d.top_name) +
        '</b> with ' + num(d.top_amount) + '</p>' : '');
    state.chip.raid = { on: d.done,
      t: 'RAID ' + Math.round(Number(d.progress) / Number(d.target) * 100) + '%' };
    paintWeekChips();
  }

  /* Badges. Earned in a league, derived from what already happened, and worn
     three at a time by choice — the board stays readable and the choice is
     itself a small statement. */
  function badgeArt(key) { return (GI_BADGE_ART && GI_BADGE_ART[key]) || 'medal'; }

  async function loadBadges() {
    var box = $('#badges'); if (!box) return;
    var r = await sb.rpc('my_badges', { p_league: state.leagueId });
    if (r.error || !r.data) { box.innerHTML = ''; return; }
    state.badges = r.data;
    var pinned = (state.profile && state.profile.pinned_badges) || [];
    var got = r.data.filter(function (b) { return b.earned; }).length;
    $('#badgeCount').textContent = got + ' / ' + r.data.length;
    box.innerHTML = r.data.map(function (b) {
      var on = pinned.indexOf(b.key) >= 0;
      var pct = Math.min(100, Number(b.progress) / Number(b.target) * 100);
      return '<button type="button" class="bdg' + (b.earned ? ' got' : '') +
        (on ? ' pinned' : '') + '" data-badge="' + b.key + '"' +
        (b.earned ? '' : ' disabled') + '>' +
        '<span class="bdg-i">' + iconSvg(badgeArt(b.key)) + '</span>' +
        '<span class="bdg-n">' + esc(b.name) + '</span>' +
        '<span class="bdg-d">' + esc(b.descr) + '</span>' +
        (b.earned ? '<span class="bdg-on">' + (on ? 'ON SHOW' : 'TAP TO WEAR') + '</span>'
          : '<span class="bdg-bar"><i style="width:' + pct.toFixed(0) + '%"></i></span>' +
            '<span class="bdg-p">' + num(b.progress) + ' / ' + num(b.target) + '</span>') +
      '</button>';
    }).join('');
  }


  /* Rivalries. Nobody at rank 12 is chasing rank 1, but they very much do not
     want to lose to rank 13. Pairings come from last week's finish so they hold
     still all week; the score is this week's live points. */
  function rivalCard(r, big) {
    var meId = state.profile ? state.profile.id : null;
    var iAmA = r.a_id === meId;
    var meSide  = iAmA ? { n: r.a_name, av: r.a_avatar, p: Number(r.a_points) }
                       : { n: r.b_name, av: r.b_avatar, p: Number(r.b_points) };
    var foeSide = iAmA ? { n: r.b_name, av: r.b_avatar, p: Number(r.b_points) }
                       : { n: r.a_name, av: r.a_avatar, p: Number(r.a_points) };
    var L = big ? meSide : { n: r.a_name, av: r.a_avatar, p: Number(r.a_points) };
    var R = big ? foeSide : { n: r.b_name, av: r.b_avatar, p: Number(r.b_points) };
    var gap = L.p - R.p;
    var cls = 'riv' + (big ? ' riv-big' : '') + (r.mine && !big ? ' mine' : '');
    return '<div class="' + cls + '">' +
      '<span class="riv-s' + (gap > 0 ? ' up' : '') + '">' +
        avatarHtml(L.av, { name: L.n, size: big ? 'lg' : 'sm' }) +
        '<b>' + esc(L.n) + '</b><i>' + num(L.p) + '</i></span>' +
      '<span class="riv-v">' + (big
        ? (gap === 0 ? 'LEVEL' : (gap > 0 ? '+' + num(gap) : num(gap)))
        : 'vs') + '</span>' +
      '<span class="riv-s' + (gap < 0 ? ' up' : '') + '">' +
        avatarHtml(R.av, { name: R.n, size: big ? 'lg' : 'sm' }) +
        '<b>' + esc(R.n) + '</b><i>' + num(R.p) + '</i></span>' +
    '</div>';
  }

  async function loadRivalries() {
    var mine = $('#myRival'), all = $('#rivalList');
    if (!mine) return;
    var r = await sb.rpc('league_rivalries', { p_league: state.leagueId });
    if (r.error || !r.data || !r.data.length) {
      mine.innerHTML = '<div class="empty">Pairings start once the league has ' +
        'a full week behind it.</div>';
      all.innerHTML = '';
      return;
    }
    var m = r.data.filter(function (x) { return x.mine; })[0];
    mine.innerHTML = m ? rivalCard(m, true)
      : '<div class="empty">You are the odd one out this week — no rival drawn.</div>';
    all.innerHTML = r.data.map(function (x) { return rivalCard(x, false); }).join('');
  }

  /* Consistency, not volume: the one table a beginner can win. */
  async function loadStreaks() {
    var box = $('#streaks'); if (!box) return;
    var r = await sb.rpc('league_streaks', { p_league: state.leagueId });
    if (r.error || !r.data) { box.innerHTML = ''; return; }
    var rows = r.data.filter(function (x) { return x.best_streak > 0; });
    var me = state.profile ? state.profile.id : null;
    /* The summary is what you see with the section shut, so it carries your
       own run rather than the league's — the leader's streak is not news
       every time you open the tab. */
    var mine = rows.filter(function (x) { return x.profile_id === me; })[0];
    $('#streakCount').textContent = !mine ? 'NO STREAK YET'
      : mine.current_streak > 0 ? 'YOU ' + mine.current_streak + ' DAYS'
      : 'YOUR BEST ' + mine.best_streak;
    if (!rows.length) {
      box.innerHTML = '<div class="empty">No streak going yet. Score 20 points two days running to start one.</div>';
      return;
    }
    box.innerHTML = rows.slice(0, 10).map(function (x, i) {
      var live = x.current_streak > 0;
      return '<div class="stk' + (x.profile_id === me ? ' me' : '') +
               (skinClass(x.banner) ? ' skin ' + skinClass(x.banner) : '') + '">' +
        '<span class="stk-r">' + (i + 1) + '</span>' +
        avatarHtml(x.avatar, { name: x.display_name, size: 'sm' }) +
        '<span class="stk-n">' + esc(x.display_name) + '</span>' +
        '<span class="stk-d' + (live ? ' live' : '') + '">' +
          (live ? x.current_streak : x.best_streak) +
          '<small>' + (live ? 'DAYS' : 'BEST') + '</small></span>' +
      '</div>';
    }).join('');
  }

  function bannerOf(lifetime) {
    /* Below the first grade you are UNRANKED rather than nothing — a row with
       no edge at all looks like a rendering fault next to rows that have one. */
    var got = { at: 0, tier: 'o', grade: 'UNRANKED', name: 'UNRANKED' };
    for (var i = 0; i < MILESTONES.length; i++) {
      if (Number(lifetime) >= MILESTONES[i].at) got = MILESTONES[i];
    }
    return got;
  }

  var UNITS = {
    reps:    { label: 'REPS',       short: 'reps', step: 1,   def: 10, quick: [5, 10, 20, 50] },
    seconds: { label: 'SECONDS',    short: 'sec',  step: 5,   def: 30, quick: [15, 30, 60, 120] },
    minutes: { label: 'MINUTES',    short: 'min',  step: 1,   def: 10, quick: [5, 10, 20, 30] },
    km:      { label: 'KILOMETRES', short: 'km',   step: 0.5, def: 5,  quick: [1, 3, 5, 10] },
    flat:    { label: 'SESSIONS',   short: 'sessions', step: 1, def: 1, quick: [1, 2, 3] }
  };

  function exercise(key) {
    for (var i = 0; i < EXERCISES.length; i++) if (EXERCISES[i].key === key) return EXERCISES[i];
    return null;
  }
  function modeOf(key, mode) {
    var ex = exercise(key); if (!ex) return null;
    for (var i = 0; i < ex.modes.length; i++) if (ex.modes[i].mode === mode) return ex.modes[i];
    return null;
  }
  /* Must agree with calc_points() in SQL to the last decimal — this only
     draws the preview, the server is what actually scores. */
  function pointsFor(key, mode, amount, bw, load) {
    var m = modeOf(key, mode); if (!m) return 0;
    if (m.gym) {
      bw = Number(bw); load = Number(load);
      if (!(bw >= 30 && bw <= 250) || !(load >= 0 && load <= 500)) return 0;
      var r = (load * m.equip + (m.legs ? 0.85 * bw : 0)) / bw;
      return Math.round(amount * m.k * r * 100) / 100;
    }
    return Math.round(amount * m.rate * 100) / 100;
  }

  /* ===================================================================
     2. Small helpers
     =================================================================== */
  var $ = function (s) { return document.querySelector(s); };
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function num(n) {
    n = Math.round(Number(n) * 100) / 100;
    return (n % 1 === 0) ? String(n) : String(Math.round(n * 10) / 10);
  }
  var toastTimer;
  function toast(msg, bad) {
    var t = $('#toast');
    t.textContent = msg;
    t.className = 'toast' + (bad ? ' bad' : '');
    t.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { t.hidden = true; }, bad ? 4200 : 2400);
  }
  var FRIENDLY = {
    LEAGUE_FULL: 'That league is full — 30 fighters maximum.',
    NO_SUCH_LEAGUE: 'No league found with that code. Check the 6 characters.',
    BAD_CODE: 'That restore code does not match any profile.',
    DEVICE_HAS_DATA: 'This phone already has a profile with workouts on it.',
    NO_PROFILE: 'Pick your name first.',
    TOO_MANY_LEAGUES: 'You already own 10 leagues.',
    NOT_SIGNED_IN: 'Connection lost — reload the page.',
    WEEK_CLOSED: 'That week is over — its entries are locked.',
    ALREADY_IN_CHALLENGE: 'You already have a duel open. Finish or cancel it first.',
    OWN_CHALLENGE: 'That is your own duel code.',
    NO_SUCH_CHALLENGE: 'No duel found with that code.',
    CHALLENGE_UNAVAILABLE: 'That duel is no longer open.',
    NOT_A_MEMBER: 'That duel belongs to a league you are not in.',
    REST_DAY: 'Sunday is a rest day — a stretching session is the only thing that counts.',
    REST_DAY_DONE: 'You already logged your recovery today. Rest.'
  };
  function niceError(e) {
    if (!e) return 'Something went wrong.';
    var m = e.message || e.error_description || String(e);
    for (var k in FRIENDLY) if (m.indexOf(k) !== -1) return FRIENDLY[k];
    if (/display_name_check|char_length/.test(m)) return 'Names must be 2 to 18 characters.';
    if (/Anonymous sign-ins are disabled/i.test(m)) {
      return 'Anonymous sign-ins are still OFF in Supabase (Authentication → Sign In / Providers).';
    }
    if (/Failed to fetch|NetworkError|load failed/i.test(m)) return 'No connection. Try again.';
    return m;
  }

  /* ===================================================================
     3. Weeks and the Sunday 23:59 deadline (timezone aware)
     =================================================================== */
  function tzOffsetMs(date, tz) {
    var dtf = new Intl.DateTimeFormat('en-US', {
      timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
    var p = {}, parts = dtf.formatToParts(date), i;
    for (i = 0; i < parts.length; i++) p[parts[i].type] = parts[i].value;
    var asUTC = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second);
    return asUTC - Math.floor(date.getTime() / 1000) * 1000;
  }
  /* "Wall clock" date: a Date whose UTC fields hold the local time in TZ. */
  function wallNow() { var n = new Date(); return new Date(n.getTime() + tzOffsetMs(n, TZ)); }
  function wallToUtcMs(wallMs) {
    var g = wallMs - tzOffsetMs(new Date(wallMs), TZ);
    return wallMs - tzOffsetMs(new Date(g), TZ);
  }
  function iso(d) {
    return d.getUTCFullYear() + '-' +
      String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +
      String(d.getUTCDate()).padStart(2, '0');
  }
  /* Monday of the current week, as YYYY-MM-DD (matches Postgres date_trunc). */
  function currentWeekStart() {
    var w = wallNow();
    var back = (w.getUTCDay() + 6) % 7;
    return iso(new Date(Date.UTC(w.getUTCFullYear(), w.getUTCMonth(), w.getUTCDate() - back)));
  }
  /* Sunday is a rest day: the league is closed and only recovery counts. */
  function isRestDay() { return wallNow().getUTCDay() === 0; }

  /* Instant of Saturday 23:59:59.999 — when the competition stops. */
  function competitionEndMs(weekStartIso) {
    var p = weekStartIso.split('-');
    return wallToUtcMs(Date.UTC(+p[0], +p[1] - 1, +p[2] + 5, 23, 59, 59, 999));
  }

  /* Instant of Sunday 23:59:59.999 that closes the given week. */
  function weekDeadlineMs(weekStartIso) {
    var p = weekStartIso.split('-');
    var wallEnd = Date.UTC(+p[0], +p[1] - 1, +p[2] + 6, 23, 59, 59, 999);
    return wallToUtcMs(wallEnd);
  }
  function weekRangeLabel(weekStartIso) {
    var p = weekStartIso.split('-');
    var a = new Date(Date.UTC(+p[0], +p[1] - 1, +p[2]));
    var b = new Date(Date.UTC(+p[0], +p[1] - 1, +p[2] + 6));
    var f = function (d) {
      return new Intl.DateTimeFormat('en-GB', {
        day: 'numeric', month: 'short', timeZone: 'UTC'
      }).format(d).toUpperCase();
    };
    return f(a) + ' – ' + f(b);
  }

  /* ===================================================================
     4. State
     =================================================================== */
  var sb = null;
  var state = {
    profile: null,
    leagues: [],
    leagueId: null,
    week: currentWeekStart(),
    board: [],
    history: [],
    open: {},          // profile ids whose activity feed is expanded
    openWeeks: {},
    feeds: {},
    feedDay: {},          // which day groups a viewer has opened
    chip: {},             // one-line summaries for the folded week strip
    weekBoxTouched: false,// once you open or shut it yourself, we stop deciding
    session: [],       // items logged inside the currently open modal
    pendingCode: null,
    view: 'live',
    statsRange: 'week',
    wins: [],
    champions: [],
    raceTo: 5,            // the target a "first to N" run is counted against
    muscles: [],
    bodyView: 'front',
    bodyPick: null,       // the region a thumb is currently holding
    duels: [],
    restDone: false
  };
  var LS = {
    league: 'ironleague.league',
    race: 'ironleague.raceto'
  };
  try {
    var savedRace = Number(localStorage.getItem(LS.race));
    if (savedRace === 3 || savedRace === 5 || savedRace === 10) state.raceTo = savedRace;
  } catch (e) {}

  /* ===================================================================
     5. Boot
     =================================================================== */
  function configured() {
    return CFG.SUPABASE_URL && CFG.SUPABASE_ANON_KEY &&
      CFG.SUPABASE_URL.indexOf('PASTE') === -1 &&
      CFG.SUPABASE_ANON_KEY.indexOf('PASTE') === -1 &&
      /^https?:\/\//.test(CFG.SUPABASE_URL);
  }
  function show(id) {
    ['#boot', '#setup', '#onboard', '#app'].forEach(function (s) {
      $(s).hidden = (s !== id);
    });
  }

  function readInviteCode() {
    var h = location.hash || '';
    var m = h.match(/join\/([A-Za-z0-9]{4,10})/) || h.match(/join=([A-Za-z0-9]{4,10})/);
    if (!m) {
      var q = new URLSearchParams(location.search);
      if (q.get('join')) m = [null, q.get('join')];
    }
    if (m) {
      try { sessionStorage.setItem('ironleague.invite', m[1].toUpperCase()); } catch (e) {}
      history.replaceState(null, '', location.pathname + location.search);
      return m[1].toUpperCase();
    }
    try { return sessionStorage.getItem('ironleague.invite'); } catch (e) { return null; }
  }

  async function boot() {
    if (CFG.APP_NAME) { $('#brandName').textContent = CFG.APP_NAME; }
    $('#version').textContent = 'IRON LEAGUE ' + APP_VERSION + ' · ' + TZ;

    if (!configured()) { show('#setup'); return; }
    if (typeof supabase === 'undefined') {
      show('#setup');
      $('#setupErr').textContent = 'Could not load vendor/supabase.js — is the whole folder uploaded?';
      return;
    }

    sb = supabase.createClient(CFG.SUPABASE_URL, CFG.SUPABASE_ANON_KEY, {
      auth: { persistSession: true, autoRefreshToken: true, storageKey: 'ironleague.auth' }
    });

    state.pendingCode = readInviteCode() || (CFG.DEFAULT_LEAGUE_CODE || '').toUpperCase() || null;

    try {
      var got = await sb.auth.getSession();
      if (!got.data.session) {
        var anon = await sb.auth.signInAnonymously();
        if (anon.error) throw anon.error;
      }
    } catch (e) {
      failSetup(e);
      return;
    }

    try { await loadProfile(); } catch (e) { toast(niceError(e), true); }

    if (!state.profile) { startOnboarding(); return; }
    await enterApp();
  }

  /* The setup screen doubles as the "cannot reach the server" screen. */
  function failSetup(e) {
    var msg = niceError(e);
    show('#setup');
    if (/connection|reload the page/i.test(msg)) {
      $('#setupTitle').innerHTML = 'NO<br><span class="accent">SIGNAL</span>';
      $('#setupIntro').textContent = 'Iron League could not reach the server.';
      $('#setupSteps').hidden = true;
      $('#setupHelp').hidden = true;
      $('#retryBtn').hidden = false;
    }
    $('#setupErr').textContent = msg;
  }
  $('#retryBtn').addEventListener('click', function () { location.reload(); });

  async function loadProfile() {
    var u = await sb.auth.getUser();
    if (!u.data || !u.data.user) return;
    var r = await sb.from('profiles').select('*').eq('user_id', u.data.user.id).maybeSingle();
    if (r.error) throw r.error;
    state.profile = r.data;
  }

  /* ===================================================================
     6. Onboarding
     =================================================================== */
  /* 'invite'  = arrived through a friend's link, league already known
     'join'    = default: type the code you were given
     'create'  = deliberately starting a new group                        */
  var onboardMode = 'join';

  function setOnboardMode(m) {
    onboardMode = m;
    $('#joinWrap').hidden      = (m !== 'join');
    $('#newLeagueWrap').hidden = (m !== 'create');
    $('#joinPreview').hidden   = (m !== 'invite');
    $('#modeToggle').hidden    = (m === 'invite');
    $('#modeToggle').textContent = (m === 'create')
      ? 'Actually, I have a league code'
      : 'No code? Start a brand new league';
    $('#enterBtn').textContent = (m === 'create') ? 'CREATE MY LEAGUE' : 'ENTER THE ARENA';
  }

  async function startOnboarding() {
    show('#onboard');
    var code = state.pendingCode;
    if (code) {
      var pv = await sb.rpc('league_preview', { p_code: code });
      var l = pv.data && pv.data[0];
      if (l) {
        $('#joinPreview').innerHTML =
          '<div class="jc-k">YOU ARE JOINING</div>' +
          '<div class="jc-n">' + esc(l.name) + '</div>' +
          '<div class="muted small mono">' + l.members + '/' + l.max_members +
          ' FIGHTERS · CODE ' + esc(l.code) + '</div>' +
          (l.members >= l.max_members
            ? '<div class="err small">This league is full.</div>' : '');
        setOnboardMode('invite');
        $('#nameInput').focus();
        return;
      }
      state.pendingCode = null;
      try { sessionStorage.removeItem('ironleague.invite'); } catch (e) {}
    }
    setOnboardMode('join');
    $('#nameInput').focus();
  }

  $('#modeToggle').addEventListener('click', function () {
    setOnboardMode(onboardMode === 'create' ? 'join' : 'create');
    $('#onboardErr').textContent = '';
  });

  /* Check the code as it is typed, so nobody discovers a typo after signing up. */
  var codeCheckTimer;
  $('#joinCode').addEventListener('input', function () {
    var v = this.value.trim().toUpperCase();
    this.value = v;
    var hint = $('#codeHint');
    clearTimeout(codeCheckTimer);
    hint.style.color = '';
    if (v.length < 6) {
      hint.className = 'muted small';
      hint.textContent = 'The 6 characters your friend sent you.';
      return;
    }
    hint.className = 'muted small';
    hint.textContent = 'Checking…';
    codeCheckTimer = setTimeout(async function () {
      try {
        var pv = await sb.rpc('league_preview', { p_code: v });
        var l = pv.data && pv.data[0];
        if (!l) {
          hint.className = 'err small';
          hint.textContent = 'No league with that code.';
        } else if (l.members >= l.max_members) {
          hint.className = 'err small';
          hint.textContent = l.name + ' is full (' + l.members + '/' + l.max_members + ').';
        } else {
          hint.className = 'small';
          hint.style.color = 'var(--green)';
          hint.textContent = '✓ ' + l.name + ' — ' + l.members + '/' + l.max_members + ' fighters';
        }
      } catch (e) { /* leave the hint as it is */ }
    }, 350);
  });

  $('#restoreToggle').addEventListener('click', function () {
    var b = $('#restoreBox'); b.hidden = !b.hidden;
    if (!b.hidden) $('#restoreInput').focus();
  });

  $('#enterForm').addEventListener('submit', async function (ev) {
    ev.preventDefault();
    var btn = $('#enterBtn');
    var name = $('#nameInput').value.trim();
    $('#onboardErr').textContent = '';
    if (name.length < 2) { $('#onboardErr').textContent = 'Name must be at least 2 characters.'; return; }
    btn.disabled = true; btn.textContent = 'ENTERING…';
    try {
      var p = await sb.rpc('create_profile', { p_name: name });
      if (p.error) throw p.error;
      state.profile = p.data;

      if (onboardMode === 'create') {
        var lname = ($('#firstLeague').value || '').trim();
        if (lname.length < 2) throw new Error('Give your new league a name.');
        var c = await sb.rpc('create_league', { p_name: lname.slice(0, 28) });
        if (c.error) throw c.error;
        state.leagueId = c.data.id;
      } else {
        var code = state.pendingCode || $('#joinCode').value.trim().toUpperCase();
        if (!code) {
          throw new Error('Enter the league code your friend sent you, ' +
                          'or tap "Start a brand new league" below.');
        }
        var j = await sb.rpc('join_league_by_code', { p_code: code });
        if (j.error) throw j.error;
        state.leagueId = j.data.id;
      }
      try { sessionStorage.removeItem('ironleague.invite'); } catch (e) {}
      state.pendingCode = null;
      localStorage.setItem(LS.league, state.leagueId);
      await enterApp();
    } catch (e) {
      $('#onboardErr').textContent = niceError(e);
    } finally {
      btn.disabled = false;
      btn.textContent = (onboardMode === 'create') ? 'CREATE MY LEAGUE' : 'ENTER THE ARENA';
    }
  });

  $('#restoreBtn').addEventListener('click', async function () {
    var code = $('#restoreInput').value.trim();
    $('#onboardErr').textContent = '';
    if (!code) return;
    try {
      var r = await sb.rpc('restore_profile', { p_code: code });
      if (r.error) throw r.error;
      state.profile = r.data;
      toast('Welcome back, ' + r.data.display_name);
      await enterApp();
    } catch (e) {
      $('#onboardErr').textContent = niceError(e);
    }
  });

  /* ===================================================================
     7. Entering the app
     =================================================================== */
  async function enterApp() {
    show('#app');
    try {
      var w = await sb.rpc('current_week_start');
      if (!w.error && w.data) state.week = w.data;
    } catch (e) { /* keep the locally computed week */ }

    await loadLeagues();

    // An invite arriving while already signed in: join it now.
    if (state.pendingCode) {
      var known = state.leagues.filter(function (l) { return l.code === state.pendingCode; })[0];
      if (known) { state.leagueId = known.id; }
      else {
        try {
          var j = await sb.rpc('join_league_by_code', { p_code: state.pendingCode });
          if (j.error) throw j.error;
          state.leagueId = j.data.id;
          toast('Joined ' + j.data.name);
          await loadLeagues();
        } catch (e) { toast(niceError(e), true); }
      }
      try { sessionStorage.removeItem('ironleague.invite'); } catch (e) {}
      state.pendingCode = null;
      localStorage.setItem(LS.league, state.leagueId);
    }

    buildExerciseSelect();
    buildPointsTable();
    buildComboRules();
    loadRestState();

    if (!state.leagues.length) { renderMe(); switchView('me'); tick(); return; }

    var saved = localStorage.getItem(LS.league);
    var ok = state.leagues.filter(function (l) { return l.id === state.leagueId; })[0] ||
             state.leagues.filter(function (l) { return l.id === saved; })[0];
    state.leagueId = (ok || state.leagues[0]).id;
    localStorage.setItem(LS.league, state.leagueId);

    renderHeader();
    tick();
    await refreshAll();
    startAutoRefresh();
  }

  function league() {
    return state.leagues.filter(function (l) { return l.id === state.leagueId; })[0] || null;
  }

  async function loadLeagues() {
    var r = await sb.rpc('my_leagues');
    if (r.error) { toast(niceError(r.error), true); return; }
    state.leagues = r.data || [];
  }

  function renderHeader() {
    var l = league();
    if (!l) return;
    var lskin = skinClass(l.badge && l.badge.skin);
    $('#leagueBtn').className = 'leaguepill' + (lskin ? ' skin ' + lskin : '');
    $('#lgBadge').innerHTML = leagueBadgeHtml(l, 'sm');
    $('#lgName').textContent = l.name;
    $('#lgName').style.color = nameColor(l.badge && l.badge.text) || '';
    $('#lgMeta').textContent = l.members + '/' + l.max_members + ' · CODE ' + l.code;
    $('#weekLabel').textContent = weekRangeLabel(state.week);
  }

  /* ===================================================================
     8. Countdown to Sunday 23:59
     =================================================================== */
  var lastWeekSeen = state.week;
  function tick() {
    var wk = currentWeekStart();
    var rest = isRestDay();
    var ms = (rest ? weekDeadlineMs(wk) : competitionEndMs(wk)) - Date.now();
    if (ms < 0) ms = 0;
    var s = Math.floor(ms / 1000);
    var d = Math.floor(s / 86400), h = Math.floor(s % 86400 / 3600),
        m = Math.floor(s % 3600 / 60), sec = s % 60;
    var pad = function (n) { return String(n).padStart(2, '0'); };
    var t = $('#cdTimer');
    t.textContent = (d > 0 ? d + 'D ' : '') + pad(h) + ':' + pad(m) + ':' + pad(sec);
    t.classList.toggle('urgent', s < 3600 * 6 && !rest);
    document.querySelector('.cd-label').textContent =
      rest ? 'REST DAY · OPENS IN' : 'LEAGUE CLOSES IN';
    $('#countdown').classList.toggle('resting', rest);

    if (state.view === 'duel') tickDuel();

    if (wk !== lastWeekSeen) {          // a new week just started
      lastWeekSeen = wk;
      state.week = wk;
      state.feeds = {};
      state.open = {};
      rollOver();
      toast('New week. Everyone back to zero.');
    }
  }
  setInterval(tick, 1000);

  async function rollOver() {
    if (!sb || !state.leagueId) return;
    try {
      var w = await sb.rpc('current_week_start');
      if (!w.error && w.data) state.week = w.data;
    } catch (e) { /* keep local value */ }
    refreshAll();
  }

  /* ===================================================================
     9. Live leaderboard
     =================================================================== */
  async function refreshAll() {
    /* allSettled, not all: one widget failing must never blank the table,
       which is the only thing on this screen that really matters. */
    var jobs = [loadBoard(), loadHistory(), loadCombo(), loadBounty(),
                loadStreaks(), loadRaid()];
    var res = await Promise.allSettled(jobs);
    res.forEach(function (x) {
      if (x.status === 'rejected' && window.console) console.error('widget failed', x.reason);
    });
    renderHeader();
  }

  async function loadBoard() {
    if (!state.leagueId) return;
    var r = await sb.rpc('league_leaderboard', { p_league: state.leagueId, p_week: state.week });
    if (r.error) { toast(niceError(r.error), true); return; }
    state.board = r.data || [];
    renderBoard();
  }

  function ranked(rows) {
    var out = [], rank = 0, prev = null;
    for (var i = 0; i < rows.length; i++) {
      var pts = Number(rows[i].points) || 0;
      if (prev === null || pts !== prev) { rank = i + 1; prev = pts; }
      out.push({ row: rows[i], rank: pts > 0 ? rank : null });
    }
    return out;
  }

  /* Divisions are a live cut of the current table: the top ten are Gold,
     the next ten Silver, the rest Bronze. Log something and you climb. */
  function withTiers(rows) {
    if (rows.length < TIER_MINIMUM) return null;     // one division is not a division
    var sorted = rows.slice().sort(function (a, b) {
      var d = Number(b.points) - Number(a.points);
      if (d) return d;
      return new Date(a.joined_at) - new Date(b.joined_at);
    });
    var out = [], i = 0;
    TIERS.forEach(function (t) {
      var members = sorted.slice(i, i + t.size);
      i += t.size;
      if (members.length) out.push({ tier: t, rows: members });
    });
    if (i < sorted.length && out.length) {          // more people than tiers allow for
      out[out.length - 1].rows = out[out.length - 1].rows.concat(sorted.slice(i));
    }
    return out;
  }

  /* `lead` is the top of whichever division this row is in, not the top of
     the league — ranks run straight through now, so it can no longer be
     worked out from the number. Each division stays its own race. */
  function boardRow(p, rank, tierKey, lead) {
    var me = state.profile ? state.profile.id : null;
    var pts = Number(p.points) || 0;
    lead = (lead === undefined ? rank === 1 : lead) && pts > 0;
    var cls = 'row' + (tierKey
        ? (lead ? ' lead-' + tierKey.toLowerCase() : '')
        : (rank && rank <= 3 && pts > 0 ? ' r' + rank : '')) +
      (p.profile_id === me ? ' me' : '');
    var open = !!state.open[p.profile_id];
    var bn = bannerOf(p.lifetime);
    var skin = skinClass(p.banner);
    return '<div class="' + cls + (bn ? ' bnr bnr-' + bn.tier : '') +
           (skin ? ' skin ' + skin : '') +
           '" data-id="' + p.profile_id + '">' +
      '<button class="rowbtn" type="button" data-toggle="' + p.profile_id + '">' +
        '<span class="rank">' + (rank && pts > 0 ? rank : '–') + '</span>' +
        avatarHtml(p.avatar, { name: p.display_name, tier: tierKey }) +
        '<span class="who"><span class="nm"' +
          (nameColor(p.name_color) ? ' style="color:' + nameColor(p.name_color) + '"' : '') +
          '>' + esc(p.display_name) +
          ((p.pinned_badges || []).length
            ? '<span class="wornrow">' + p.pinned_badges.map(function (k) {
                return '<span class="worn">' + iconSvg(badgeArt(k)) + '</span>';
              }).join('') + '</span>' : '') +
          (p.profile_id === me ? ' <span class="muted" style="font-size:11px">(YOU)</span>' : '') +
        '</span>' +
        '<span class="sub">' +
          (bn ? '<b class="rankchip rank-' + bn.tier + '">' + bn.name + '</b> · ' : '') +
          p.entries + (Number(p.entries) === 1 ? ' entry' : ' entries') +
          (Number(p.bonus) > 0 ? ' · <b class="cbadge">+' + num(p.bonus) + ' combo</b>' : '') +
        '</span></span>' +
        '<span class="pts">' + num(pts) + '<small>PTS</small></span>' +
        '<span class="chev">' + (open ? '▲' : '▼') + '</span>' +
      '</button>' +
      (open ? '<div class="feed" data-feed="' + p.profile_id + '">' +
                (state.feeds[p.profile_id] ? feedHtml(state.feeds[p.profile_id]) :
                 '<div class="muted small" style="padding:8px 0">Loading…</div>') +
              '</div>' : '') +
    '</div>';
  }

  function renderBoard() {
    var box = $('#board');
    if (!state.board.length) {
      box.innerHTML = '<div class="empty">Nobody here yet. Share your link!</div>';
      return;
    }
    var groups = withTiers(state.board);
    if (groups) {
      var mine = state.profile ? state.profile.id : null;
      var seen = 0, numbering = null;
      box.innerHTML = groups.map(function (g) {
        var here = g.rows.some(function (p) { return p.profile_id === mine; });
        if (g.tier.rank !== numbering) { seen = 0; numbering = g.tier.rank; }
        return '<div class="divhead t-' + g.tier.key.toLowerCase() +
                 (here ? ' is-mine' : '') + '">' +
                 '<span class="divhead-c">' + iconSvg(g.tier.icon) + '</span>' +
                 '<span class="divhead-t"><b>' + g.tier.name + ' DIVISION</b>' +
                   '<i>' + g.tier.sub + '</i></span>' +
                 '<span class="divhead-n">' + g.rows.length + '</span>' +
               '</div>' +
               g.rows.map(function (p, i) {
                 seen += 1;
                 return boardRow(p, p.points > 0 ? seen : null, g.tier.key, i === 0);
               }).join('');
      }).join('') +
      '<p class="hint">The top five are numbered straight through; every ' +
      'division below counts from one. Pass the person above you and you ' +
      'take their place.</p>';
      return;
    }
    var me = state.profile ? state.profile.id : null;
    var html = ranked(state.board).map(function (r) {
      return boardRow(r.row, r.rank, null);
    }).join('');
    box.innerHTML = html;
  }

  function feedHtml(rows) {
    if (!rows.length) return '<div class="muted small" style="padding:8px 0">Nothing logged this week.</div>';
    var me = state.profile ? state.profile.id : null;

    /* A busy week is forty lines long. Group by day and collapse all but the
       most recent, so opening someone's feed shows a week at a glance. */
    var days = [], byDay = {};
    rows.forEach(function (w) {
      var when = new Date(w.created_at);
      var key = new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(when);
      if (!byDay[key]) { byDay[key] = { key: key, when: when, rows: [], pts: 0 }; days.push(byDay[key]); }
      byDay[key].rows.push(w);
      byDay[key].pts += Number(w.points) || 0;
    });
    days.sort(function (a, b) { return b.key < a.key ? -1 : 1; });

    return days.map(function (d, i) {
      var open = state.feedDay[d.key] !== undefined ? state.feedDay[d.key] : i === 0;
      var label = new Intl.DateTimeFormat('en-GB',
        { weekday: 'long', day: 'numeric', month: 'short', timeZone: TZ }).format(d.when);
      return '<div class="fday' + (open ? ' open' : '') + '">' +
        '<button type="button" class="fday-h" data-day="' + d.key + '">' +
          '<span class="fday-x">' + (open ? '▴' : '▾') + '</span>' +
          '<span class="fday-n">' + esc(label.toUpperCase()) + '</span>' +
          '<span class="fday-c">' + d.rows.length + '</span>' +
          '<span class="fday-p">+' + num(d.pts) + '</span>' +
        '</button>' +
        (open ? d.rows.map(function (w) {
          var ex = exercise(w.exercise_key);
          var u = unitFor(w.exercise_key, w.mode);
          var hh = new Intl.DateTimeFormat('en-GB',
            { hour: '2-digit', minute: '2-digit', hourCycle: 'h23', timeZone: TZ })
            .format(new Date(w.created_at));
          return '<div class="fitem">' +
            '<span class="fx">' + esc(ex ? ex.name : w.exercise_key) +
              '<span class="famt"> · ' + num(w.amount) + ' ' + u.short + ' · ' + hh + '</span></span>' +
            '<span class="fpts">+' + num(w.points) +
              (Number(w.boost) > 1 ? '<span class="boost">&times;' + w.boost + '</span>' : '') +
            '</span>' +
            (w.profile_id === me && !isRestDay()
              ? '<button class="del" data-edit="' + w.id + '" title="Edit">✎</button>' +
                '<button class="del" data-del="' + w.id + '" title="Delete">✕</button>'
              : '') +
          '</div>';
        }).join('') : '') +
      '</div>';
    }).join('');
  }

  async function loadFeed(profileId) {
    var r = await sb.from('workouts').select('*')
      .eq('league_id', state.leagueId)
      .eq('profile_id', profileId)
      .eq('week_start', state.week)
      .order('created_at', { ascending: false });
    if (r.error) { toast(niceError(r.error), true); return; }
    state.feeds[profileId] = r.data || [];
    var box = document.querySelector('[data-feed="' + profileId + '"]');
    if (box) box.innerHTML = feedHtml(state.feeds[profileId]);
  }

  document.addEventListener('click', function (e) {
    var h = e.target.closest('[data-day]'); if (!h) return;
    var k = h.getAttribute('data-day');
    var open = h.parentNode.classList.contains('open');
    state.feedDay[k] = !open;
    var feed = h.closest('.feed');
    var pid = feed && feed.getAttribute('data-feed');
    if (pid && state.feeds[pid]) feed.innerHTML = feedHtml(state.feeds[pid]);
  });

  $('#board').addEventListener('click', async function (e) {
    var ed = e.target.closest('[data-edit]');
    if (ed) {
      e.stopPropagation();
      openEdit(ed.getAttribute('data-edit'));
      return;
    }
    var del = e.target.closest('[data-del]');
    if (del) {
      e.stopPropagation();
      if (!confirm('Delete this entry?')) return;
      var target = findEntry(del.getAttribute('data-del'));
      var r = await sb.from('workouts').delete()
                .eq('group_id', target ? target.group_id : del.getAttribute('data-del'))
                .select();
      if (r.error) { toast(niceError(r.error), true); return; }
      if (!r.data || !r.data.length) {
        toast('That week is over — its entries are locked.', true); return;
      }
      state.feeds = {};
      toast('Entry deleted');
      await refreshAll();
      Object.keys(state.open).forEach(function (id) { if (state.open[id]) loadFeed(id); });
      return;
    }
    var btn = e.target.closest('[data-toggle]');
    if (!btn) return;
    var id = btn.getAttribute('data-toggle');
    state.open[id] = !state.open[id];
    renderBoard();
    if (state.open[id] && !state.feeds[id]) loadFeed(id);
  });

  /* ===================================================================
     10. Hall of fame
     =================================================================== */
  async function loadHistory() {
    if (!state.leagueId) return;
    var r = await sb.rpc('weekly_history', { p_league: state.leagueId });
    if (r.error) { toast(niceError(r.error), true); return; }
    state.history = r.data || [];
    renderHall();

    var w = await sb.rpc('league_wins', { p_league: state.leagueId });
    if (!w.error) state.wins = w.data || [];
    var c = await sb.rpc('league_champions', { p_league: state.leagueId });
    if (!c.error) state.champions = c.data || [];
    renderWins();
  }

  /* Cut the run of weekly champions into races to N.
     Somebody reaching N ends that run there: the weeks after it belong to the
     next one, and everybody starts the next one on zero. Doing it here rather
     than in the database is what lets the target be a switch on the phone —
     change it and every past run is re-cut on the spot, with nothing stored
     and nothing to migrate. */
  function cutRuns(champions, target) {
    var runs = [], tally = {}, weeks = 0;
    (champions || []).forEach(function (c) {
      tally[c.profile_id] = (tally[c.profile_id] || 0) + 1;
      weeks++;
      if (tally[c.profile_id] >= target) {
        runs.push({ winner: c, weeks: weeks, ended: c.week_start });
        tally = {}; weeks = 0;
      }
    });
    return { done: runs, tally: tally, weeks: weeks, n: runs.length + 1 };
  }

  /* Crowns. One per week won, counted from the same finished weeks the hall
     below is built from, so the two can never tell different stories. The
     race target is a local choice — nothing about "first to five" needs to be
     agreed with the server, and making it a league setting would mean one
     person deciding it for everybody. */
  function renderWins() {
    var box = $('#wins');
    var rows = state.wins || [];
    var weeks = rows.length ? Number(rows[0].weeks) : 0;
    if (!weeks) {
      $('#winsWeeks').textContent = 'NOT STARTED';
      box.innerHTML = '<div class="empty">No week has finished yet.<br>' +
        'The first crown is handed out on Sunday at 23:59.</div>';
      return;
    }
    var target = state.raceTo;
    var run = cutRuns(state.champions, target);
    var lead = Math.max.apply(null, [0].concat(rows.map(function (r) {
      return run.tally[r.profile_id] || 0; })));

    /* A shut section still has to be worth reading, so the summary carries
       the only two numbers that matter: which run, and where you are in it. */
    var me = rows.filter(function (r) { return r.mine; })[0];
    $('#winsWeeks').textContent = 'RUN ' + run.n + ' · YOU ' +
      ((me && run.tally[me.profile_id]) || 0) + '/' + target;

    /* Runs already taken, most recent first. This is the answer to "what
       happens when somebody gets there": their name goes up here for good,
       the board resets to zero, and the next run starts the following week. */
    var past = run.done.length
      ? '<div class="runs">' + run.done.slice().reverse().map(function (r, i) {
          return '<span class="run"><i>RUN ' + (run.done.length - i) + '</i>' +
            avatarHtml(r.winner.avatar, { name: r.winner.display_name, size: 'sm' }) +
            '<b>' + esc(r.winner.display_name) + '</b>' +
            '<em>' + r.weeks + (r.weeks === 1 ? ' week' : ' weeks') + '</em></span>';
        }).join('') + '</div>'
      : '';

    box.innerHTML = past +
      '<div class="runhead"><span>RUN ' + run.n + ' · FIRST TO ' + target + '</span>' +
        '<i>' + (run.weeks
          ? run.weeks + (run.weeks === 1 ? ' week in' : ' weeks in')
          : 'starts with the next week') + '</i></div>' +
      /* Only the people actually in the race, plus you. A league of thirty
         renders twenty-eight rows of "0 / 5" otherwise, and the three names
         that matter get lost in it. */
      (function () {
        var inIt = rows.filter(function (r) {
          return (run.tally[r.profile_id] || 0) > 0 || r.mine; });
        var rest = rows.length - inIt.length;
        return inIt.map(function (r) {
          var here = run.tally[r.profile_id] || 0;
          var life = Number(r.wins);
          var pct = Math.min(100, here / target * 100);
          return '<div class="win' + (r.mine ? ' me' : '') +
              (here && here === lead ? ' lead' : '') + '">' +
            '<span class="win-w">' + avatarHtml(r.avatar,
                { name: r.display_name, size: 'sm' }) +
              '<b>' + esc(r.display_name) + '</b>' +
              '<i>' + (life ? crowns(life) + ' all time' : 'no crown yet') + '</i></span>' +
            '<span class="win-n">' + here + '<em>/' + target + '</em></span>' +
            '<span class="win-bar"><span style="width:' + pct.toFixed(1) + '%"></span></span>' +
          '</div>';
        }).join('') + (rest > 0
          ? '<p class="restline">and ' + rest + ' others yet to win a week in this run</p>'
          : '');
      })() +
      '<p class="hint">' + (lead
        ? (target - lead) + (target - lead === 1 ? ' week' : ' weeks') +
          ' from the front. Reach ' + target + ' and the run is yours — the board ' +
          'clears and run ' + (run.n + 1) + ' starts the Monday after.'
        : 'Everyone starts on zero. First to ' + target + ' takes the run.') + '</p>';
  }

  /* Five crowns is a row of five; twelve is a crown and a number. Nobody can
     count fourteen little pictures anyway. */
  function crowns(n) {
    if (!n) return '';
    if (n <= 4) return new Array(n + 1).join('<i class="cr">👑</i>');
    return '<i class="cr">👑</i><b class="crx">x' + n + '</b>';
  }

  window.__cutRuns__ = cutRuns;   // the run maths, reachable from a test
  window.__fixFor__ = fixFor;
  window.__EXNAME__ = function (k) { var e = exercise(k); return e ? e.name : k; };

  $('#winsRace').addEventListener('click', function (e) {
    var b = e.target.closest('[data-race]'); if (!b) return;
    state.raceTo = Number(b.getAttribute('data-race'));
    try { localStorage.setItem(LS.race, String(state.raceTo)); } catch (err) {}
    Array.prototype.forEach.call(this.querySelectorAll('button'), function (x) {
      x.classList.toggle('on', x === b);
    });
    renderWins();
  });

  function renderHall() {
    var box = $('#hall');
    if (!state.history.length) {
      box.innerHTML = '<div class="empty">No finished week yet.<br>' +
        'The first champion is crowned on Sunday at 23:59.</div>';
      return;
    }
    var weeks = [], byWeek = {};
    state.history.forEach(function (r) {
      if (!byWeek[r.week_start]) { byWeek[r.week_start] = []; weeks.push(r.week_start); }
      byWeek[r.week_start].push(r);
    });
    box.innerHTML = weeks.map(function (wk, wi) {
      var rows = byWeek[wk].slice().sort(function (a, b) { return b.points - a.points; });
      var win = rows[0];
      var open = !!state.openWeeks[wk];

      /* Most improved: biggest gain on your own previous week. You have to
         have been there the week before, so nobody wins it by appearing. */
      var prevWk = weeks[wi + 1], climber = null;
      if (prevWk) {
        var prev = {};
        byWeek[prevWk].forEach(function (r) { prev[r.profile_id] = Number(r.points); });
        rows.forEach(function (r) {
          if (prev[r.profile_id] === undefined) return;
          var gain = Number(r.points) - prev[r.profile_id];
          if (gain > 0 && (!climber || gain > climber.gain)) {
            climber = { row: r, gain: gain };
          }
        });
      }
      return '<div class="week">' +
        '<button class="week-top" type="button" data-week="' + wk + '">' +
          '<span class="crown">👑</span>' +
          '<span><span class="week-when">' + weekRangeLabel(wk) + '</span>' +
            '<span class="week-who" style="display:block">' +
              avatarHtml(win.avatar, { name: win.display_name, size: 'sm' }) +
              esc(win.display_name) + '</span></span>' +
          '<span class="week-pts">' + num(win.points) + '<br>' +
            '<span class="muted" style="font-size:10px;letter-spacing:.14em">PTS</span></span>' +
          '<span class="week-chev">' + (open ? '▲' : '▼') + '</span>' +
        '</button>' +
        (climber ? '<div class="climber"><span class="cl-i">📈</span>' +
            '<span class="cl-t">MOST IMPROVED</span>' +
            '<span class="cl-n">' + avatarHtml(climber.row.avatar,
                 { name: climber.row.display_name, size: 'sm' }) +
              esc(climber.row.display_name) + '</span>' +
            '<span class="cl-g">+' + num(climber.gain) + '</span></div>' : '') +
        (open ? '<div class="week-body">' + rows.map(function (r, i) {
            return '<div class="mini"><span class="mn">' + (i + 1) + '. ' + esc(r.display_name) +
                   '</span><span class="mp">' + num(r.points) + ' pts · ' + r.entries + '</span></div>';
          }).join('') + '</div>' : '') +
      '</div>';
    }).join('');
  }

  $('#hall').addEventListener('click', function (e) {
    var b = e.target.closest('[data-week]');
    if (!b) return;
    var wk = b.getAttribute('data-week');
    state.openWeeks[wk] = !state.openWeeks[wk];
    renderHall();
  });

  /* ===================================================================
     11. Leagues / profile tab
     =================================================================== */
  function shareUrl(code) {
    return location.origin + location.pathname + '#/join/' + code;
  }

  function renderMe() {
    var box = $('#leagueList');
    if (!state.leagues.length) {
      box.innerHTML = '<div class="empty">You are not in a league yet.<br>' +
        'Create one below, or open a friend\'s invite link.</div>';
    } else {
      box.innerHTML = state.leagues.map(function (l) {
        var full = l.members >= l.max_members;
        return '<button class="lg-card' + (l.id === state.leagueId ? ' active' : '') +
          '" type="button" data-league="' + l.id + '">' +
          leagueBadgeHtml(l, 'md') +
          '<span><span class="t">' + esc(l.name) + '</span>' +
          '<span class="s">CODE ' + esc(l.code) +
          (state.profile && l.owner_id === state.profile.id ? ' · YOURS' : '') + '</span></span>' +
          '<span class="cap' + (full ? ' full' : '') + '">' + l.members + '/' + l.max_members + '</span>' +
        '</button>';
      }).join('');
    }
    var l = league();
    if (l) {
      var cur = badgeOf(l);
      var chosen = l.badge || {};
      $('#optCrest').innerHTML = leagueBadgeHtml(l, 'sm') +
        (chosen.emblem ? ' ' + esc(cur.emblem.replace(/-/g, ' '))
                       : ' Auto — from the league code');
      $('#optBanner').textContent = chosen.skin
        ? (skinName(chosen.skin) || chosen.skin) : 'Nothing yet';
      $('#optMetal').textContent =
        (chosen.shape ? cur.shape : cur.shape + ' (auto)') + ' · ' +
        (chosen.color ? cur.color : cur.color + ' (auto)');
    }
    $('#shareLink').value = l ? shareUrl(l.code) : '—';
    if (state.profile) {
      $('#renameInput').value = state.profile.display_name;
      $('#bwProfile').value = state.profile.bodyweight
        ? Math.round(fromKg(state.profile.bodyweight) * 10) / 10 : '';
      paintUnits();
      paintForm();
      $('#restoreCode').textContent = state.profile.restore_code;
      buildAvatarGrid();
      paintNameColors();
    }
    paintLeagueRules();
    buildShop();
    if ($('#sectEmblem').open) buildAvatarGridsOnce();
    if (navigator.share) $('#shareBtn').hidden = !l;
  }

